create table if not exists public.money_accounts (id uuid primary key default gen_random_uuid(),company_id uuid not null,name text not null,account_type text not null default 'bank' check(account_type in ('cash','bank','mobile_money','pos','other')),opening_balance numeric not null default 0,is_active boolean not null default true,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.money_account_movements (id uuid primary key default gen_random_uuid(),company_id uuid not null,account_id uuid not null references public.money_accounts(id) on delete restrict,direction text not null check(direction in ('in','out')),amount numeric not null check(amount>0),category text not null default 'other',description text not null,occurred_at timestamptz not null default now(),transfer_group_id uuid,created_by uuid,created_at timestamptz not null default now());
create index if not exists money_accounts_company_idx on public.money_accounts(company_id,is_active);
create index if not exists money_account_movements_account_date_idx on public.money_account_movements(account_id,occurred_at desc);
create index if not exists money_account_movements_company_date_idx on public.money_account_movements(company_id,occurred_at desc);
alter table public.money_accounts enable row level security;
alter table public.money_account_movements enable row level security;
drop policy if exists money_accounts_select_owner on public.money_accounts; create policy money_accounts_select_owner on public.money_accounts for select to authenticated using(company_id=public.get_my_company_id() and public.has_permission('profit'));
drop policy if exists money_accounts_insert_owner on public.money_accounts; create policy money_accounts_insert_owner on public.money_accounts for insert to authenticated with check(company_id=public.get_my_company_id() and public.has_permission('profit'));
drop policy if exists money_accounts_update_owner on public.money_accounts; create policy money_accounts_update_owner on public.money_accounts for update to authenticated using(company_id=public.get_my_company_id() and public.has_permission('profit')) with check(company_id=public.get_my_company_id() and public.has_permission('profit'));
drop policy if exists money_account_movements_select_owner on public.money_account_movements; create policy money_account_movements_select_owner on public.money_account_movements for select to authenticated using(company_id=public.get_my_company_id() and public.has_permission('profit'));
drop policy if exists money_account_movements_insert_owner on public.money_account_movements; create policy money_account_movements_insert_owner on public.money_account_movements for insert to authenticated with check(company_id=public.get_my_company_id() and public.has_permission('profit'));
create or replace function public.transfer_money_between_accounts(p_from_account uuid,p_to_account uuid,p_amount numeric,p_description text,p_occurred_at timestamptz default now()) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid();v_company uuid:=public.get_my_company_id();v_group uuid:=gen_random_uuid();v_from_company uuid;v_to_company uuid;begin if v_user is null then raise exception 'Not authenticated';end if;if not public.has_permission('profit') then raise exception 'Permission denied';end if;if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero';end if;if p_from_account=p_to_account then raise exception 'Choose two different accounts';end if;select company_id into v_from_company from public.money_accounts where id=p_from_account and is_active=true;select company_id into v_to_company from public.money_accounts where id=p_to_account and is_active=true;if v_from_company is null or v_to_company is null or v_from_company<>v_company or v_to_company<>v_company then raise exception 'Account not found or access denied';end if;insert into public.money_account_movements(company_id,account_id,direction,amount,category,description,occurred_at,transfer_group_id,created_by) values(v_company,p_from_account,'out',p_amount,'transfer',p_description,p_occurred_at,v_group,v_user),(v_company,p_to_account,'in',p_amount,'transfer',p_description,p_occurred_at,v_group,v_user);return v_group;end;$$;
revoke all on function public.transfer_money_between_accounts(uuid,uuid,numeric,text,timestamptz) from public;
grant execute on function public.transfer_money_between_accounts(uuid,uuid,numeric,text,timestamptz) to authenticated;
